insert into public.resort_info (resort_key, data, version, updated_by)
select s.resort_key, s.data, 1, '2027 안내문 초안'
from seed s
on conflict (resort_key) do update
set data = jsonb_build_object(
      'origins', case when jsonb_array_length(coalesce(resort_info.data->'origins', '[]'::jsonb)) > 0
                      then resort_info.data->'origins' else excluded.data->'origins' end,
      'items',   coalesce(excluded.data->'items', '{}'::jsonb) || coalesce(resort_info.data->'items', '{}'::jsonb),
      'extra',   coalesce(resort_info.data->'extra', '[]'::jsonb)
                 || coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(excluded.data->'extra', '[]'::jsonb)) x
                              where not exists (select 1 from jsonb_array_elements(coalesce(resort_info.data->'extra', '[]'::jsonb)) y
                                                 where y->>'label' = x->>'label')), '[]'::jsonb)),
    version    = resort_info.version + 1,
    updated_by = '2027 안내문 초안(병합)'
where (coalesce(excluded.data->'items', '{}'::jsonb) || coalesce(resort_info.data->'items', '{}'::jsonb))
        is distinct from coalesce(resort_info.data->'items', '{}'::jsonb)
   or (jsonb_array_length(coalesce(resort_info.data->'origins', '[]'::jsonb)) = 0
       and jsonb_array_length(coalesce(excluded.data->'origins', '[]'::jsonb)) > 0)
   or exists (select 1 from jsonb_array_elements(coalesce(excluded.data->'extra', '[]'::jsonb)) x
              where not exists (select 1 from jsonb_array_elements(coalesce(resort_info.data->'extra', '[]'::jsonb)) y
                                 where y->>'label' = x->>'label'));
